rule CobaltStrike_Shellcode {
    meta:
        description = "Detects encoded Cobalt Strike shellcode patterns"
        author = "SOC_Team"
        maltype = "Backdoor"
    strings:
        $a = { 60 00 00 00 61 6D 6F 75 6E 74 }
        $b = { 2E 72 64 61 74 00 00 00 }
        $c = { 4D 5A [0-32] 50 45 [0-128] E8 [4] 00 00 00 }
    condition:
        all of them
}

